    }
    frame(lua_state, 45.0); // 23
    FT_MOTION_RATE_RANGE(agent, 45.0, 120.0, 56.0); // end 120
    if is_excute(agent) {
        agent.on_flag(*FIGHTER_MASTER_STATUS_SPECIAL_N_FLAG_RELEASE_BUTTON); // using to spawn fx once
